css:
/* ============================================================
   LIFE ERP — TASK MANAGER / TICKET SYSTEM
   FULL CLEAN CSS REWRITE — LIFE GREEN THEME
   Color reference: Life Sales Master Data
   No CSS variable / var() usage
   ============================================================ */

#life-tt-app,
.life-tt-app {
  width: 100%;
  min-height: 100vh;
  background: #F3FAF4;
  color: #152418;
  font-family: Arial, sans-serif;
  font-size: 12px;
  line-height: 1.45;
  border-radius: 12px;
  overflow: hidden;
}

#life-tt-app *,
.life-tt-app * {
  box-sizing: border-box;
}

.navbar { display: none; }
.web-footer { display: none; }

/* ============================================================
   HEADER
   ============================================================ */

#life-tt-app .header,
.life-tt-app .header {
  /*background: #0F3D1E;*/
  /*color: #FFFFFF;*/
  /*padding: 14px 22px;*/
  /*display: flex;*/
  /*align-items: center;*/
  /*justify-content: space-between;*/
  /*gap: 14px;*/
  /*flex-wrap: wrap;*/
  display:none;
}

#life-tt-app .header .h1,
.life-tt-app .header .h1 {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.4px;
  line-height: 1.25;
}

#life-tt-app .header .sub,
.life-tt-app .header .sub {
  font-size: 10.5px;
  color: rgba(255,255,255,0.72);
  margin-top: 3px;
  font-weight: 600;
}

#life-tt-app .logged-user-box,
.life-tt-app .logged-user-box {
  min-width: 210px;
  background: #1B5E20;
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 8px;
  padding: 8px 12px;
}

#life-tt-app .logged-user-box label,
.life-tt-app .logged-user-box label {
  display: block;
  margin-bottom: 3px;
  color: rgba(255,255,255,0.68);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.5px;
}

#life-tt-app #logged-in-user-name,
.life-tt-app #logged-in-user-name {
  color: #FFFFFF;
  font-size: 12px;
  font-weight: 900;
}

#life-tt-app #logged-in-user-role,
.life-tt-app #logged-in-user-role {
  margin-top: 2px;
  color: rgba(255,255,255,0.72);
  font-size: 10px;
  font-weight: 700;
}

#life-tt-app .gold-bar,
.life-tt-app .gold-bar {
  height: 3px;
  background: #43A047;
}

/* ============================================================
   PAGE CONTENT
   ============================================================ */

#life-tt-app .content,
.life-tt-app .content {
  max-width: 1560px;
  margin: 0 auto;
  padding: 18px 20px 28px;
}

/* ============================================================
   TASK / TICKET MAIN TOGGLE
   ============================================================ */

#life-tt-app .type-toggle,
.life-tt-app .type-toggle {
  display: flex;
  align-items: stretch;
  justify-content: flex-start;
  gap: 14px;
  flex-wrap: wrap;
  margin: 8px 0 16px;
}

#life-tt-app .type-btn,
.life-tt-app .type-btn {
  width: 300px;
  max-width: 100%;
  min-height: 78px;
  background: #FFFFFF;
  border: 2px solid #DCE9DE;
  border-radius: 12px;
  padding: 14px 16px;
  cursor: pointer;
  text-align: center;
  transition: 0.18s ease;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

#life-tt-app .type-btn:hover,
.life-tt-app .type-btn:hover {
  border-color: #0F3D1E;
  box-shadow: 0 5px 16px rgba(15,61,30,0.12);
  transform: translateY(-1px);
}

#life-tt-app .type-btn.sel,
.life-tt-app .type-btn.sel {
  border-color: #43A047;
  background: #E8F5E9;
  box-shadow: 0 4px 14px rgba(67,160,71,0.14);
}

#life-tt-app .type-btn .tt,
.life-tt-app .type-btn .tt {
  color: #0F3D1E;
  font-size: 13px;
  font-weight: 900;
}

#life-tt-app .type-btn .ts,
.life-tt-app .type-btn .ts {
  margin-top: 4px;
  color: #5F6F63;
  font-size: 10px;
  font-weight: 700;
}

#life-tt-app .type-btn .cnt,
.life-tt-app .type-btn .cnt {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 18px;
  margin-left: 6px;
  padding: 0 7px;
  border-radius: 20px;
  background: #C00000;
  color: #FFFFFF;
  font-size: 9px;
  font-weight: 900;
}

/* ============================================================
   REFRESH ROW
   ============================================================ */

#life-tt-app .life-refresh-row,
.life-tt-app .life-refresh-row {
  margin: 0 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

#life-tt-app .life-tab-note,
.life-tt-app .life-tab-note {
  flex: 1;
  min-height: 38px;
  background: #FFFFFF;
  border-left: 4px solid #43A047;
  border-radius: 8px;
  padding: 9px 13px;
  color: #0F3D1E;
  font-size: 11.5px;
  font-weight: 800;
  line-height: 1.4;
  box-shadow: 0 1px 5px rgba(15,61,30,0.08);
}

#life-tt-app .life-refresh-actions,
.life-tt-app .life-refresh-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-shrink: 0;
}

#life-tt-app .life-refresh-note,
.life-tt-app .life-refresh-note {
  color: #5F6F63;
  font-size: 10.5px;
  font-weight: 700;
}

#life-tt-app .life-refresh-btn,
.life-tt-app .life-refresh-btn {
  height: 34px;
  border: none;
  border-radius: 7px;
  background: #0F3D1E;
  color: #FFFFFF;
  padding: 0 16px;
  font-size: 11.5px;
  font-weight: 900;
  cursor: pointer;
}

#life-tt-app .life-refresh-btn:hover,
.life-tt-app .life-refresh-btn:hover {
  background: #14501F;
}

#life-tt-app .life-refresh-btn:disabled,
.life-tt-app .life-refresh-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ============================================================
   SUB NAVIGATION
   ============================================================ */

#life-tt-app .sub-nav,
.life-tt-app .sub-nav {
  display: flex;
  align-items: stretch;
  gap: 0;
  margin-bottom: 16px;
  border-bottom: 2px solid #43A047;
  overflow-x: auto;
  background: #FFFFFF;
  border-radius: 9px 9px 0 0;
}

#life-tt-app .snav,
.life-tt-app .snav {
  min-width: 170px;
  padding: 12px 16px;
  text-align: center;
  color: #52665A;
  background: #F8FCF8;
  border-right: 1px solid #DCE9DE;
  border-bottom: 3px solid transparent;
  font-size: 11.5px;
  font-weight: 900;
  cursor: pointer;
  white-space: nowrap;
  margin-bottom: -2px;
}

#life-tt-app .snav:last-child,
.life-tt-app .snav:last-child {
  border-right: none;
}

#life-tt-app .snav:hover,
.life-tt-app .snav:hover {
  color: #0F3D1E;
  background: #FFFFFF;
}

#life-tt-app .snav.on,
.life-tt-app .snav.on {
  color: #0F3D1E;
  background: #FFFFFF;
  border-bottom-color: #43A047;
}

/* ============================================================
   MODULE / SUBPAGE VISIBILITY
   ============================================================ */

#life-tt-app .module,
.life-tt-app .module,
#life-tt-app .subpage,
.life-tt-app .subpage {
  display: none;
}

#life-tt-app .module.on,
.life-tt-app .module.on,
#life-tt-app .subpage.on,
.life-tt-app .subpage.on {
  display: block;
}

/* ============================================================
   CARDS
   ============================================================ */

#life-tt-app .card,
.life-tt-app .card {
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 10px;
  margin-bottom: 16px;
  overflow: hidden;
  box-shadow: 0 2px 10px rgba(15,61,30,0.06);
}

#life-tt-app .card-hdr,
.life-tt-app .card-hdr {
  min-height: 42px;
  background: #0F3D1E;
  color: #FFFFFF;
  padding: 11px 15px;
  font-size: 12.5px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

#life-tt-app .card-hdr .badge,
.life-tt-app .card-hdr .badge {
  background: #43A047;
  color: #FFFFFF;
  border-radius: 20px;
  padding: 2px 9px;
  font-size: 9.5px;
  font-weight: 900;
}

#life-tt-app .card-body,
.life-tt-app .card-body {
  padding: 16px;
}

/* ============================================================
   FORMS
   ============================================================ */

#life-tt-app .two-col,
.life-tt-app .two-col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

#life-tt-app .three-col,
.life-tt-app .three-col {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

#life-tt-app .field-block,
.life-tt-app .field-block {
  margin-bottom: 13px;
}

#life-tt-app label.lbl,
.life-tt-app label.lbl {
  display: block;
  margin-bottom: 5px;
  color: #0F3D1E;
  font-size: 9.5px;
  font-weight: 900;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

#life-tt-app .required-mark,
.life-tt-app .required-mark {
  color: #C00000;
}

#life-tt-app input[type="text"],
#life-tt-app input[type="date"],
#life-tt-app input[type="datetime-local"],
#life-tt-app input[type="number"],
#life-tt-app input[type="email"],
#life-tt-app input[type="tel"],
#life-tt-app select,
#life-tt-app textarea,
.life-tt-app input[type="text"],
.life-tt-app input[type="date"],
.life-tt-app input[type="datetime-local"],
.life-tt-app input[type="number"],
.life-tt-app input[type="email"],
.life-tt-app input[type="tel"],
.life-tt-app select,
.life-tt-app textarea {
  width: 100%;
  border: 1.5px solid #DCE9DE;
  border-radius: 6px;
  background: #FFFFFF;
  color: #152418;
  font-family: Arial, sans-serif;
  font-size: 11.5px;
  outline: none;
  transition: 0.15s ease;
}

#life-tt-app input,
#life-tt-app select,
.life-tt-app input,
.life-tt-app select {
  height: 34px;
  padding: 6px 9px;
}

#life-tt-app textarea,
.life-tt-app textarea {
  min-height: 76px;
  padding: 8px 9px;
  line-height: 1.45;
  resize: vertical;
}

#life-tt-app input:focus,
#life-tt-app select:focus,
#life-tt-app textarea:focus,
.life-tt-app input:focus,
.life-tt-app select:focus,
.life-tt-app textarea:focus {
  border-color: #0F3D1E;
  box-shadow: 0 0 0 3px rgba(15,61,30,0.08);
}

#life-tt-app input:disabled,
.life-tt-app input:disabled {
  background: #EEF4EF;
  color: #52665A;
  cursor: not-allowed;
}

#life-tt-app .wordcount,
.life-tt-app .wordcount,
#life-tt-app .life-delay-wordcount,
.life-tt-app .life-delay-wordcount {
  margin-top: 3px;
  color: #5F6F63;
  font-size: 9.5px;
  font-weight: 700;
  text-align: right;
}

#life-tt-app .wordcount.over,
.life-tt-app .wordcount.over,
#life-tt-app .life-delay-wordcount.over,
.life-tt-app .life-delay-wordcount.over {
  color: #C00000;
  font-weight: 900;
}

/* ============================================================
   BUTTONS
   ============================================================ */

#life-tt-app .btn,
.life-tt-app .btn,
#life-tt-app .apbtn,
.life-tt-app .apbtn {
  border: none;
  border-radius: 6px;
  padding: 9px 17px;
  font-size: 11.5px;
  font-weight: 900;
  cursor: pointer;
  line-height: 1.2;
  transition: 0.15s ease;
  text-align: center;
}

#life-tt-app .btn-sm,
.life-tt-app .btn-sm {
  padding: 6px 11px;
  font-size: 10.5px;
}

#life-tt-app .btn-n,
.life-tt-app .btn-n,
#life-tt-app .apbtn,
.life-tt-app .apbtn {
  background: #0F3D1E;
  color: #FFFFFF;
}

#life-tt-app .btn-n:hover,
.life-tt-app .btn-n:hover,
#life-tt-app .apbtn:hover,
.life-tt-app .apbtn:hover {
  background: #14501F;
}

#life-tt-app .btn-g,
.life-tt-app .btn-g {
  background: #2E7D32;
  color: #FFFFFF;
}

#life-tt-app .btn-g:hover,
.life-tt-app .btn-g:hover {
  background: #14501F;
}

#life-tt-app .btn-gy,
.life-tt-app .btn-gy {
  background: #F0F2F5;
  color: #52665A;
  border: 1px solid #CFE1D2;
}

#life-tt-app .btn-gy:hover,
.life-tt-app .btn-gy:hover {
  background: #E8F5E9;
}

#life-tt-app .btn-info,
.life-tt-app .btn-info {
  background: #0F3D1E;
  color: #FFFFFF;
  border: 1px solid #0F3D1E;
}

#life-tt-app .btn-info:hover,
.life-tt-app .btn-info:hover {
  background: #14501F;
}

#life-tt-app .btn-review,
.life-tt-app .btn-review,
#life-tt-app .btn-deadline,
.life-tt-app .btn-deadline {
  background: #43A047;
  color: #FFFFFF;
}

#life-tt-app .btn-review:hover,
.life-tt-app .btn-review:hover,
#life-tt-app .btn-deadline:hover,
.life-tt-app .btn-deadline:hover {
  background: #946B08;
}

#life-tt-app .btn-undo,
.life-tt-app .btn-undo {
  background: #FFFFFF;
  color: #0F3D1E;
  border: 1px solid #0F3D1E;
}

#life-tt-app .btn-undo:hover,
.life-tt-app .btn-undo:hover {
  background: #0F3D1E;
  color: #FFFFFF;
}

#life-tt-app .btn:disabled,
.life-tt-app .btn:disabled,
#life-tt-app .apbtn:disabled,
.life-tt-app .apbtn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ============================================================
   PRIORITY CHIPS
   ============================================================ */

#life-tt-app .priority-grp,
.life-tt-app .priority-grp {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

#life-tt-app .priority-chip,
.life-tt-app .priority-chip {
  min-width: 82px;
  padding: 8px 14px;
  border: 1.5px solid #CFE1D2;
  border-radius: 7px;
  background: #FFFFFF;
  color: #35633D;
  font-size: 11px;
  font-weight: 900;
  text-align: center;
  cursor: pointer;
}

#life-tt-app .priority-chip[data-p="High"].sel,
.life-tt-app .priority-chip[data-p="High"].sel {
  border-color: #C00000;
  background: #FBE9E7;
  color: #C00000;
}

#life-tt-app .priority-chip[data-p="Medium"].sel,
.life-tt-app .priority-chip[data-p="Medium"].sel {
  border-color: #C96A00;
  background: #FFF3E0;
  color: #C96A00;
}

#life-tt-app .priority-chip[data-p="Low"].sel,
.life-tt-app .priority-chip[data-p="Low"].sel {
  border-color: #2E7D32;
  background: #E8F5E9;
  color: #2E7D32;
}

/* ============================================================
   PICKER / USER SEARCH
   ============================================================ */

#life-tt-app .picker-wrap,
.life-tt-app .picker-wrap {
  position: relative;
}

#life-tt-app .picker-results,
.life-tt-app .picker-results {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  z-index: 90;
  display: none;
  max-height: 230px;
  overflow-y: auto;
  margin-top: 4px;
  background: #FFFFFF;
  border: 1.5px solid #0F3D1E;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15,61,30,0.18);
}

#life-tt-app .picker-results.show,
.life-tt-app .picker-results.show {
  display: block;
}

#life-tt-app .picker-item,
.life-tt-app .picker-item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 10px;
  border-bottom: 1px solid #EEF4EF;
  cursor: pointer;
}

#life-tt-app .picker-item:last-child,
.life-tt-app .picker-item:last-child {
  border-bottom: none;
}

#life-tt-app .picker-item:hover,
.life-tt-app .picker-item:hover {
  background: #E8F5E9;
}

#life-tt-app .picker-avatar,
.life-tt-app .picker-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #0F3D1E;
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 900;
  flex-shrink: 0;
}

#life-tt-app .picker-name,
.life-tt-app .picker-name {
  color: #0F3D1E;
  font-size: 11px;
  font-weight: 900;
}

#life-tt-app .picker-role,
.life-tt-app .picker-role {
  margin-top: 1px;
  color: #5F6F63;
  font-size: 9.5px;
  font-weight: 700;
}

#life-tt-app .selected-chip-row,
.life-tt-app .selected-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 7px;
}

#life-tt-app .selected-chip,
.life-tt-app .selected-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #EEF4EF;
  color: #0F3D1E;
  border-radius: 20px;
  padding: 5px 10px;
  font-size: 10.5px;
  font-weight: 900;
}

#life-tt-app .selected-chip.locked,
.life-tt-app .selected-chip.locked {
  background: #E8F5E9;
  color: #43A047;
}

#life-tt-app .selected-chip .x,
.life-tt-app .selected-chip .x {
  color: #C00000;
  cursor: pointer;
  font-weight: 900;
}

/* ============================================================
   ATTACHMENTS
   ============================================================ */

#life-tt-app .attach-zone,
.life-tt-app .attach-zone {
  border: 2px dashed #CFE1D2;
  border-radius: 8px;
  background: #FAFCFA;
  padding: 15px;
  color: #5F6F63;
  text-align: center;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

#life-tt-app .attach-zone:hover,
.life-tt-app .attach-zone:hover {
  border-color: #0F3D1E;
  background: #E8F5E9;
  color: #0F3D1E;
}

#life-tt-app .attach-list,
.life-tt-app .attach-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 8px;
}

#life-tt-app .attach-item,
.life-tt-app .attach-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: #EEF4EF;
  border: 1px solid #DCE9DE;
  border-radius: 7px;
  padding: 8px 10px;
}

#life-tt-app .attach-item .an,
.life-tt-app .attach-item .an {
  color: #0F3D1E;
  font-size: 11px;
  font-weight: 900;
  word-break: break-word;
}

#life-tt-app .attach-item .asize,
.life-tt-app .attach-item .asize {
  color: #5F6F63;
  font-size: 10px;
  font-weight: 700;
}

#life-tt-app .attach-item .x,
.life-tt-app .attach-item .x {
  color: #C00000;
  font-size: 14px;
  font-weight: 900;
  cursor: pointer;
}

/* ============================================================
   FILTER BAR / TILES
   ============================================================ */

#life-tt-app .fbar,
.life-tt-app .fbar {
  display: flex;
  align-items: end;
  gap: 12px;
  flex-wrap: wrap;
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 16px;
  box-shadow: 0 2px 10px rgba(15,61,30,0.05);
}

#life-tt-app .fbar > div,
.life-tt-app .fbar > div {
  min-width: 180px;
}

#life-tt-app .fbar input,
#life-tt-app .fbar select,
.life-tt-app .fbar input,
.life-tt-app .fbar select {
  height: 33px;
}

#life-tt-app .tiles,
.life-tt-app .tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

#life-tt-app .tile,
.life-tt-app .tile {
  background: #FFFFFF;
  border: 1px solid #DCE9DE;
  border-radius: 10px;
  padding: 14px;
  box-shadow: 0 2px 10px rgba(15,61,30,0.05);
}

#life-tt-app .tile .tl,
.life-tt-app .tile .tl {
  color: #5F6F63;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}

#life-tt-app .tile .tv,
.life-tt-app .tile .tv {
  margin-top: 5px;
  color: #0F3D1E;
  font-size: 22px;
  font-weight: 900;
}

#life-tt-app .t-pn,
.life-tt-app .t-pn {
  border-left: 5px solid #0F3D1E;
}

#life-tt-app .t-pg,
.life-tt-app .t-pg {
  border-left: 5px solid #2E7D32;
}

