  function fillSelect(selector, rows, firstLabel) {
    var el = $(selector);
    if (!el) return;

    var html = "";

    if (firstLabel !== "") {
      html += '<option value="">' + esc(firstLabel) + "</option>";
    }

    html += rows.map(function (x) {
      return '<option value="' + esc(x) + '">' + esc(x) + "</option>";
    }).join("");

