  function setPickerSelected(key, value) {
    if (key === "taskAssignTo") taskAssignTo = value;
    if (key === "taskUpdateTo") taskUpdateTo = value;
    if (key === "ticketTagTo") ticketTagTo = value;
    if (key === "ticketCcTo") ticketCcTo = value;
