      btn.disabled = true;
      btn.textContent = "Submitting...";
    }

    frappe.call({
      method: "frappe.client.insert",
      args: {
        doc: doc
      },
      callback: function (r) {
        var saved = r.message || {};

        uploadFiles("Issue", saved.name, ticketFiles)
          .then(function () {
            showModal("✅", "Ticket Submitted", "Ticket " + saved.name + " has been submitted and tagged to " + userLabel(tagTo) + ".");
