            loadTickets();

            if (btn) {
              btn.disabled = false;
              btn.textContent = "✓ Submit Ticket";
            }
          });
      },
      error: function (err) {
        showModal("⚠️", "Ticket Save Failed", getErrorMessage(err));

        if (btn) {
          btn.disabled = false;
          btn.textContent = "✓ Submit Ticket";
        }
      }
    });
