            'Reopen Ticket' +
          '</button>' +
        '</div>';
    }

    return '<span class="pill p-o">Waiting for Raiser Review</span>';
  }

  if (isTicketResolver(t, meta)) {
    return '' +
      '<button class="btn btn-g btn-sm ticket-resolve-btn" data-name="' + esc(t.name) + '">' +
        'Resolve Ticket' +
