function getTicketStatus(t) {
  var meta = getTicketMeta(t);

  if (t.status === "Closed") {
    return "Closed";
  }

  if (t.status === "Resolved") {
    return "Resolved";
  }

  if (meta.workflow_state === "Reopened" && t.status === "Open") {
    return "Reopened";
  }

  return t.status || "Open";
}



