    var newNo = Number(input ? input.value : 0);

    if (!Number.isFinite(newNo) || newNo < 1) {
      showModal(
        "⚠️",
        "Invalid Task Number",
        "Please enter a valid task number starting from 1."
      );
      return;
    }

    closeEdit();
    moveTaskInQueue(name, newNo);
  }

