    btn.dataset.boundAssigneeGroup = "1";

    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();

      var assignee = btn.dataset.assignee || "";

      if (assignee && assignee !== "Unassigned") {
        openManageQueueDialog(assignee);
